  document.querySelectorAll('[data-result-end]').forEach(el => { const label = now() < Number(el.dataset.resultEnd) ? 'Two games won · End match' : 'Record result'; if (el.dataset.label !== label) { el.dataset.label = label; el.innerHTML = `${icon('coins')} ${label}`; } });
  document.querySelectorAll('.board-card.playing').forEach(card => {
    const timer = card.querySelector('[data-timer]');
    if (timer && Number(timer.dataset.timer) <= now()) {
      card.querySelector('.board-card-head .badge').textContent = 'Time up';
      card.querySelector('.timer-area > span').textContent = 'TIME UP · COUNT COINS LEFT';
    }
  });
